//! Typed successor byte-coordinate domains and their checked arithmetic.
//!
//! The UTF-8 internal coordinate constitution
//! (`docs/arch/kernel/coordinates.md`) gives every position a named coordinate
//! domain, and this module is its code: `CD1` source bytes (from the start of
//! an authored file), `CD3` generated bytes (from the start of one generated
//! surface) and `CD4` embedded bytes (into cooked or derived text whose bytes
//! are not the authored bytes). Each domain is a distinct newtype pair —
//! [`SourceByteOffset`]/[`SourceByteRange`],
//! [`GeneratedByteOffset`]/[`GeneratedByteRange`] and
//! [`EmbeddedByteOffset`]/[`EmbeddedByteRange`] — so mixing domains is a
//! compile error, not a debug session.
//!
//! Rules encoded here (constitution `R01`–`R10`):
//!
//! - Construction from a raw integer is explicit ([`SourceByteOffset::new`] or
//!   the tuple form, kept for existing callers); there is no `From<u32>`,
//!   `Deref`, `as`-style coercion or `Add<u32>`, and no arithmetic, comparison
//!   or assignment across domains.
//! - Checked arithmetic refuses instead of saturating, wrapping or clamping:
//!   every failure is a typed [`CoordError`]. Nothing snaps to the nearest
//!   character or token.
//! - A conversion runs against the exact content snapshot the position indexes
//!   (`R03`); requester encodings (UTF-16/UTF-32 code units, line/column
//!   forms) enter and leave only through the checked converters here, which
//!   the boundary owners call. No converted mirror of a document is cached
//!   (`R05`).
//! - The line/column converters speak the TypeScript-wire form already owned
//!   by [`crate::Utf16LineIndex`] (1-based line, 1-based UTF-16 column, the
//!   `getLineStarts` terminator set). They are that form's exact-or-refused
//!   counterpart: [`crate::Utf16LineIndex`] applies the wire's clamps, these
//!   refuse. Another wire's base or terminator set converts in its own
//!   adapter, through byte offsets (`R10`).
//! - The ASCII fast path inside the unit converters is a differential
//!   optimisation, never an assumption (`R07`): generated surfaces carry
//!   authored non-ASCII identifiers and literals.
//!
//! # Domain mixing is a compile error
//!
//! Adding, subtracting or comparing offsets of different domains does not
//! compile. Within one domain, ordering and checked arithmetic exist:
//!
//! ```
//! use verter_span::SourceByteOffset;
//!
//! let start = SourceByteOffset::new(4);
//! let end = start.checked_add(6).unwrap();
//! assert!(start < end);
//! assert_eq!(end.checked_sub(start), Ok(SourceByteOffset::new(6)));
//! ```
//!
//! ```compile_fail
//! use verter_span::{EmbeddedByteOffset, GeneratedByteOffset, SourceByteOffset};
//!
//! let source = SourceByteOffset::new(1);
//! let generated = GeneratedByteOffset::new(2);
//! let _ = source + generated; // no Add between domains
//! ```
//!
//! ```compile_fail
//! use verter_span::{GeneratedByteOffset, SourceByteOffset};
//!
//! let source = SourceByteOffset::new(1);
//! let generated = GeneratedByteOffset::new(2);
//! let _ = source < generated; // no cross-domain comparison
//! ```
//!
//! ```compile_fail
//! use verter_span::{EmbeddedByteOffset, SourceByteOffset};
//!
//! fn embedded_extent(embedded: EmbeddedByteOffset) -> u32 {
//!     embedded.get()
//! }
//! // A source offset is not an embedded offset; there is no `From` either way.
//! embedded_extent(SourceByteOffset::new(1));
//! ```
//!
//! And no implicit conversion from a raw integer exists — only the explicit
//! constructors accept one:
//!
//! ```compile_fail
//! use verter_span::SourceByteOffset;
//!
//! let _: SourceByteOffset = 7u32.into(); // no From<u32>
//! ```
//!
//! ```compile_fail
//! use verter_span::SourceByteOffset;
//!
//! let _ = SourceByteOffset::new(1) + 1u32; // no Add<u32>
//! ```

use crate::utf16_line_index::LineCol;
use std::fmt;

/// The typed failure vocabulary of the checked coordinate API (the case
/// table's `errorVocabulary`): every refusal names one of these, and nothing
/// clamps, saturates, wraps or snaps instead.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CoordError {
    /// The offset or range is outside its domain's extent in the content it
    /// was checked against, or a range is inverted. Never normalised: an
    /// inverted range is not swapped or emptied, a past-end offset is not
    /// clamped to end-of-file.
    InvalidBoundary,
    /// Checked arithmetic left the `u32` width (overflow or underflow). Never
    /// saturated or wrapped.
    Overflow,
    /// The offset lands inside a UTF-8 sequence, or a requester offset lands
    /// inside a surrogate pair. Never snapped to the nearest boundary.
    NotCharBoundary,
}

impl fmt::Display for CoordError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CoordError::InvalidBoundary => {
                f.write_str("coordinate is outside its content extent or inverted")
            }
            CoordError::Overflow => f.write_str("checked coordinate arithmetic left u32"),
            CoordError::NotCharBoundary => {
                f.write_str("coordinate does not land on a character boundary")
            }
        }
    }
}

impl std::error::Error for CoordError {}

/// Defines one coordinate domain: a `#[repr(transparent)]` byte-offset newtype
/// plus its `#[repr(C)]` half-open range, with the same checked surface for
/// every domain (only the domain differs — never the operations).
macro_rules! coord_domain {
    (
        $(#[$offset_doc:meta])*
        $offset:ident,
        $(#[$range_doc:meta])*
        $range:ident
    ) => {
        $(#[$offset_doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[repr(transparent)]
        pub struct $offset(pub u32);

        impl $offset {
            /// The explicit named constructor from a raw byte offset. Together
            /// with the tuple form (kept for existing callers) this is the only
            /// raw-integer entry point; no `From<u32>`, `Deref` or `Add<u32>`
            /// exists.
            #[inline]
            pub const fn new(offset: u32) -> Self {
                Self(offset)
            }

            /// The raw UTF-8 byte offset.
            #[inline]
            pub const fn get(self) -> u32 {
                self.0
            }

            /// Advance by `len` bytes (the relative-to-absolute rebase is
            /// `base.checked_add(relative)`), refusing to leave the `u32`
            /// width with [`CoordError::Overflow`].
            #[inline]
            pub fn checked_add(self, len: u32) -> Result<Self, CoordError> {
                self.0
                    .checked_add(len)
                    .map(Self)
                    .ok_or(CoordError::Overflow)
            }

            /// Rebase below `base`, where both offsets are of this one domain.
            /// A base greater than the offset is [`CoordError::Overflow`] —
            /// refused, never wrapped or saturated.
            #[inline]
            pub fn checked_sub(self, base: Self) -> Result<Self, CoordError> {
                self.0
                    .checked_sub(base.0)
                    .map(Self)
                    .ok_or(CoordError::Overflow)
            }

            /// Check this offset against the exact content snapshot it
            /// indexes: past the end is [`CoordError::InvalidBoundary`]
            /// (end-of-file itself is valid), inside a UTF-8 sequence is
            /// [`CoordError::NotCharBoundary`]. Never clamped or snapped.
            pub fn validate(self, content: &str) -> Result<Self, CoordError> {
                let raw = self.0 as usize;
                if raw > content.len() {
                    return Err(CoordError::InvalidBoundary);
                }
                if !content.is_char_boundary(raw) {
                    return Err(CoordError::NotCharBoundary);
                }
                Ok(self)
            }

            /// Checked ingress from a requester UTF-16 code-unit offset
            /// (`R03`: against the exact content snapshot). A unit offset
            /// inside a surrogate pair is [`CoordError::NotCharBoundary`];
            /// past the content's unit length is
            /// [`CoordError::InvalidBoundary`].
            pub fn from_utf16(content: &str, units: u32) -> Result<Self, CoordError> {
                if content.is_ascii() {
                    return if units as usize <= content.len() {
                        Ok(Self(units))
                    } else {
                        Err(CoordError::InvalidBoundary)
                    };
                }
                let mut seen = 0u32;
                for (byte, ch) in content.char_indices() {
                    if seen == units {
                        return Ok(Self(byte as u32));
                    }
                    let ch_units = ch.len_utf16() as u32;
                    if units < seen + ch_units {
                        // Strictly inside this scalar's UTF-16 units — the
                        // second unit of a surrogate pair.
                        return Err(CoordError::NotCharBoundary);
                    }
                    seen += ch_units;
                }
                if seen == units {
                    return Ok(Self(content.len() as u32));
                }
                Err(CoordError::InvalidBoundary)
            }

            /// Checked egress to a UTF-16 code-unit offset, after validating
            /// this offset against the same content snapshot.
            pub fn to_utf16(self, content: &str) -> Result<u32, CoordError> {
                self.validate(content)?;
                if content.is_ascii() {
                    return Ok(self.0);
                }
                let mut units = 0u32;
                for (byte, ch) in content.char_indices() {
                    if byte == self.0 as usize {
                        return Ok(units);
                    }
                    units += ch.len_utf16() as u32;
                }
                // validate() guarantees we only fall out at end-of-file.
                Ok(units)
            }

            /// Checked ingress from a requester UTF-32 scalar offset. Every
            /// scalar count in extent is a scalar boundary, so only extent is
            /// refused ([`CoordError::InvalidBoundary`]).
            pub fn from_utf32(content: &str, scalars: u32) -> Result<Self, CoordError> {
                if content.is_ascii() {
                    return if scalars as usize <= content.len() {
                        Ok(Self(scalars))
                    } else {
                        Err(CoordError::InvalidBoundary)
                    };
                }
                let mut seen = 0u32;
                for (byte, _) in content.char_indices() {
                    if seen == scalars {
                        return Ok(Self(byte as u32));
                    }
                    seen += 1;
                }
                if seen == scalars {
                    return Ok(Self(content.len() as u32));
                }
                Err(CoordError::InvalidBoundary)
            }

            /// Checked egress to a UTF-32 scalar offset, after validating
            /// this offset against the same content snapshot.
            pub fn to_utf32(self, content: &str) -> Result<u32, CoordError> {
                self.validate(content)?;
                if content.is_ascii() {
                    return Ok(self.0);
                }
                let mut scalars = 0u32;
                for (byte, _) in content.char_indices() {
                    if byte == self.0 as usize {
                        return Ok(scalars);
                    }
                    scalars += 1;
                }
                Ok(scalars)
            }

            /// Convert to the TypeScript-wire line/column form ([`LineCol`]:
            /// 1-based line, 1-based UTF-16 column, the `getLineStarts`
            /// terminator set — `\n`, a lone `\r`, U+2028, U+2029, and `\r\n`
            /// as ONE terminator). Exact or refused: a byte offset between the
            /// `\r` and the `\n` of a CRLF pair lies inside a two-byte
            /// terminator and has no line/column position
            /// ([`CoordError::InvalidBoundary`]).
            pub fn line_col(self, content: &str) -> Result<LineCol, CoordError> {
                self.validate(content)?;
                let mut line = 1u32;
                let mut line_start_u16 = 0u32;
                let mut u16_idx = 0u32;
                let mut chars = content.char_indices().peekable();
                while let Some((byte, ch)) = chars.next() {
                    if byte == self.0 as usize {
                        return Ok(LineCol {
                            line,
                            col: u16_idx - line_start_u16 + 1,
                        });
                    }
                    let mut units = ch.len_utf16() as u32;
                    let is_terminator = match ch {
                        '\n' | '\u{2028}' | '\u{2029}' => true,
                        '\r' => {
                            if chars.peek().map(|&(_, c)| c) == Some('\n') {
                                if self.0 as usize == byte + 1 {
                                    // Between the two bytes of a CRLF pair:
                                    // no line/column position exists there.
                                    return Err(CoordError::InvalidBoundary);
                                }
                                let _ = chars.next();
                                units += 1;
                            }
                            true
                        }
                        _ => false,
                    };
                    u16_idx += units;
                    if is_terminator {
                        line += 1;
                        line_start_u16 = u16_idx;
                    }
                }
                // validate() guarantees we only reach here at end-of-file.
                Ok(LineCol {
                    line,
                    col: u16_idx - line_start_u16 + 1,
                })
            }

            /// Checked ingress from the TypeScript-wire line/column form
            /// ([`LineCol`]). Exact or refused: a line past the content's
            /// line count, a column more than one unit past the line's units
            /// (one unit past is the line's end boundary), or a column inside
            /// a surrogate pair ([`CoordError::NotCharBoundary`]) is a typed
            /// error — a column past the line end is never clamped to it.
            pub fn from_line_col(content: &str, pos: LineCol) -> Result<Self, CoordError> {
                if pos.line == 0 || pos.col == 0 {
                    // The form is 1-based; a 0 in either field names no
                    // position.
                    return Err(CoordError::InvalidBoundary);
                }
                let want_units = pos.col - 1;
                let mut line = 1u32;
                let mut line_start_u16 = 0u32;
                let mut u16_idx = 0u32;
                let mut chars = content.char_indices().peekable();
                while let Some((byte, ch)) = chars.next() {
                    if line == pos.line {
                        let into_line = u16_idx - line_start_u16;
                        let ch_units = ch.len_utf16() as u32;
                        if into_line == want_units {
                            return Ok(Self(byte as u32));
                        }
                        if want_units < into_line + ch_units {
                            // Strictly inside this scalar's UTF-16 units.
                            return Err(CoordError::NotCharBoundary);
                        }
                    }
                    let mut units = ch.len_utf16() as u32;
                    let is_terminator = match ch {
                        '\n' | '\u{2028}' | '\u{2029}' => true,
                        '\r' => {
                            if chars.peek().map(|&(_, c)| c) == Some('\n') {
                                let _ = chars.next();
                                units += 1;
                            }
                            true
                        }
                        _ => false,
                    };
                    u16_idx += units;
                    if is_terminator {
                        line += 1;
                        line_start_u16 = u16_idx;
                    }
                }
                if line == pos.line && u16_idx - line_start_u16 == want_units {
                    // End-of-file (or a content-final line's end).
                    return Ok(Self(content.len() as u32));
                }
                Err(CoordError::InvalidBoundary)
            }
        }

        $(#[$range_doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[repr(C)]
        pub struct $range {
            /// Inclusive start, in this domain's bytes.
            pub start: $offset,
            /// Exclusive end, in this domain's bytes.
            pub end: $offset,
        }

        impl $range {
            /// Construct from already-ordered offsets (the infallible form
            /// existing callers use for geometry they have already validated).
            /// The range constructor that rejects an inverted range is
            /// [`Self::checked_new`].
            #[inline]
            pub const fn new(start: $offset, end: $offset) -> Self {
                Self { start, end }
            }

            /// Construct, refusing an inverted range: `end < start` is
            /// [`CoordError::InvalidBoundary`] — never swapped or emptied.
            #[inline]
            pub fn checked_new(start: $offset, end: $offset) -> Result<Self, CoordError> {
                if end.0 < start.0 {
                    return Err(CoordError::InvalidBoundary);
                }
                Ok(Self { start, end })
            }

            /// Length in this domain's bytes. Total for every constructible
            /// range (an inverted one reports 0); the routes that must reject
            /// inversion are [`Self::checked_new`] and [`Self::validate`].
            #[inline]
            pub fn len(&self) -> u32 {
                self.end.0.saturating_sub(self.start.0)
            }

            #[inline]
            pub fn is_empty(&self) -> bool {
                self.start.0 >= self.end.0
            }

            /// Check both endpoints against the exact content snapshot:
            /// inverted or past-the-end is [`CoordError::InvalidBoundary`]; an
            /// endpoint inside a UTF-8 sequence is
            /// [`CoordError::NotCharBoundary`]. An empty range at offset 0 or
            /// at end-of-file is valid.
            pub fn validate(&self, content: &str) -> Result<Self, CoordError> {
                if self.end.0 < self.start.0 {
                    return Err(CoordError::InvalidBoundary);
                }
                self.start.validate(content)?;
                self.end.validate(content)?;
                Ok(*self)
            }
        }
    };
}

coord_domain! {
    /// Byte offset into the source coordinate domain (`CD1`): UTF-8 bytes from
    /// the start of an authored file (carrier or plain module).
    SourceByteOffset,
    /// Half-open `[start, end)` byte range in the source coordinate domain
    /// (`CD1`).
    SourceByteRange
}

coord_domain! {
    /// Byte offset into the generated coordinate domain (`CD3`): UTF-8 bytes
    /// from the start of one generated surface (IDE TSX, compiled output,
    /// companion).
    GeneratedByteOffset,
    /// Half-open `[start, end)` byte range in the generated coordinate domain
    /// (`CD3`).
    GeneratedByteRange
}

coord_domain! {
    /// Byte offset into the embedded coordinate domain (`CD4`): UTF-8 bytes
    /// into the cooked or derived text of a region whose bytes are not its
    /// authored bytes.
    EmbeddedByteOffset,
    /// Half-open `[start, end)` byte range in the embedded coordinate domain
    /// (`CD4`).
    EmbeddedByteRange
}

/// Length in bytes of a generated-surface content region (the
/// `content_offset` domain of `CD3`). A length carries no position, so it has
/// no checked-conversion surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(transparent)]
pub struct GeneratedByteLen(pub u32);

